import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZNov04PreambleMasksOracle extends GhidraScript{static final long RET=0x12345000L,S=0x7fff0000L,U=0x1000000L;long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}void call(EmulatorHelper e,long f)throws Exception{put(e,S,4,RET);e.writeRegister("ESP",S);e.writeRegister("ECX",U);e.writeRegister("EIP",f);e.getEmulator().setHalt(false);for(int i=0;i<20000;i++){if(e.readRegister("EIP").longValue()==RET)return;if(!e.step(monitor))throw new Exception(e.getLastError());}throw new Exception("budget");}public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int world=0;world<2;world++)for(int cls:new int[]{0,3})for(int team=0;team<2;team++)for(int role:new int[]{-1,0,1}){EmulatorHelper e=new EmulatorHelper(currentProgram);try{e.writeMemory(toAddr(U),new byte[192]);put(e,0x622dc4,1,0);put(e,0x622c7a,2,0);put(e,0x625eae,1,world==1?3:0);call(e,0x433b30);put(e,U+0x7c,1,cls);put(e,U+0x30,1,4);put(e,U+0x31,1,team);put(e,U+0x5e,1,role);call(e,0x41b950);out.print("{\"world\":"+world+",\"class\":"+cls+",\"team\":"+team+",\"role\":"+role);for(int off:new int[]{24,28}){long table=read(e,U+off,4);out.print(",\"ptr"+off+"\":"+table+",\"bytes"+off+"\":[");for(int j=0;j<67;j++)out.print((j==0?"":",")+read(e,table+j,1));out.print("]");}out.println("}");}finally{e.dispose();}}}}}
